use vstd::prelude::*;

type Matrix<T> = Vec<Vec<T>>;

verus! {

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> (ret: Matrix<i8>)
    requires
        // one‐dimensional array nonempty
        a.len() > 0,
        // shape is exactly two‐dimensional and positive
        shape.len() == 2,
        shape[0] > 0,
        shape[1] > 0,
        // array length matches one of the dimensions
        a.len() == shape[0] as usize || a.len() == shape[1] as usize,
    ensures
        // result has R rows
        ret.len() == shape[0] as usize,
        // each row has C columns
        forall(|i: usize| i < shape[0] as usize ==> ret[i].len() == shape[1] as usize),
        // broadcasting property holds
        forall(|i: usize, j: usize| 
            i < shape[0] as usize && j < shape[1] as usize ==>
            ret[i][j] ==
              if a.len() == shape[0] as usize {
                // column‐vector broadcast
                a[i]
              } else {
                // row‐vector broadcast
                a[j]
              }
        ),
{
    let R = shape[0] as usize;
    let C = shape[1] as usize;
    let mut ret: Matrix<i8> = Vec::with_capacity(R);

    // build each row i = 0..R
    let mut i: usize = 0;
    while i < R
        invariant
            i <= R,
            // we've built i rows so far
            ret.len() == i,
            // and each built row satisfies the broadcast property
            forall(|i0: usize, j: usize|
                i0 < i && j < C ==>
                ret[i0][j] ==
                  if a.len() == R { a[i0] } else { a[j] }
            ),
        decreases R - i,
    {
        // build row i
        let mut row: Vec<i8> = Vec::with_capacity(C);
        let mut j: usize = 0;
        while j < C
            invariant
                j <= C,
                // we've pushed j elements into row
                row.len() == j,
                // and those satisfy the broadcast property
                forall(|j0: usize|
                    j0 < j ==>
                    row[j0] ==
                      if a.len() == R { a[i] } else { a[j0] }
                ),
            decreases C - j,
        {
            let elem: i8 =
              if a.len() == R {
                // broadcasting down columns
                a[i]
              } else {
                // broadcasting across rows
                a[j]
              };
            row.push(elem);
            j += 1;
        }
        // finish row i
        ret.push(row);
        i += 1;
    }

    ret
}

} // end verus!

